def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    c = [float(b["c"]) for b in bars]
    lag = int(ctx.p.lag)
    sb = [0] * n
    ss = [0] * n
    for t in range(n):
        if t < lag:
            continue
        if c[t] < c[t - lag]:
            sb[t] = sb[t - 1] + 1
        if c[t] > c[t - lag]:
            ss[t] = ss[t - 1] + 1
    ctx.sb = ctx.series(sb, "seq_buy")
    ctx.ss = ctx.series(ss, "seq_sell")


def signal(ctx, i):
    if i < 3:
        return 0
    cnt = int(ctx.p.count)
    want = int(ctx.p.perfect)
    b, s = ctx.sb[i], ctx.ss[i]
    if b is not None and b >= cnt:
        if not want:
            return 1
        l0, l1 = ctx.l[i], ctx.l[i - 1]
        l2, l3 = ctx.l[i - 2], ctx.l[i - 3]
        if (l0 < l2 and l0 < l3) or (l1 < l2 and l1 < l3):
            return 1
        return 0
    if s is not None and s >= cnt:
        if not want:
            return -1
        h0, h1 = ctx.h[i], ctx.h[i - 1]
        h2, h3 = ctx.h[i - 2], ctx.h[i - 3]
        if (h0 > h2 and h0 > h3) or (h1 > h2 and h1 > h3):
            return -1
        return 0
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    cnt = int(ctx.p.count)
    if ctx.positions[0]["side"] == "long":
        v = ctx.ss[i]
    else:
        v = ctx.sb[i]
    return v is not None and v >= cnt
